size_t i;
size_t fastest_index = SIZE_MAX;
double max_abs_speed = -1.0;
adcs_vec3_t axis;
adcs_vec3_t term;
double energy_acc = 0.0;
double momentum_norm_value;

if ((wheels == NULL) || (momentum == NULL) || (momentum_norm == NULL) ||
    (energy == NULL) || (fastest == NULL)) {
    if (momentum != NULL) {
        momentum->x = 0.0;
        momentum->y = 0.0;
        momentum->z = 0.0;
    }
    if (momentum_norm != NULL) {
        *momentum_norm = 0.0;
    }
    if (energy != NULL) {
        *energy = 0.0;
    }
    if (fastest != NULL) {
        *fastest = SIZE_MAX;
    }
    return ADCS_E_NULL;
}

*momentum = (adcs_vec3_t){0.0, 0.0, 0.0};
*momentum_norm = 0.0;
*energy = 0.0;
*fastest = SIZE_MAX;

if (count != 4U) {
    return ADCS_E_RANGE;
}

for (i = 0; i < count; i++) {
    if ((!isfinite(wheels[i].inertia_kg_m2)) || (wheels[i].inertia_kg_m2 <= 0.0) ||
        (!isfinite(wheels[i].speed_rad_s))) {
        return ADCS_E_RANGE;
    }
    if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
}

for (i = 0; i < count; i++) {
    if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
    term = adcs_vec3_scale(&axis, wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s);
    *momentum = adcs_vec3_add(momentum, &term);
    energy_acc += 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;

    if (fabs(wheels[i].speed_rad_s) > max_abs_speed) {
        max_abs_speed = fabs(wheels[i].speed_rad_s);
        fastest_index = i;
    }
}

momentum_norm_value = adcs_vec3_norm(momentum);

*momentum_norm = momentum_norm_value;
*energy = energy_acc;
*fastest = fastest_index;

return ADCS_OK;

